package cn.shixu.app.test;
import android.app.*;import android.content.*;import android.os.*;import android.database.Cursor;import android.view.accessibility.*;import cn.shixu.app.*;import org.json.*;import java.time.*;import java.util.*;
/** Covers install data retention and small-screen reachable controls using only own fixtures. */
public final class AuditLifecycleInstrumentation extends SmokeInstrumentation {
    String mode;
    @Override public void onCreate(Bundle b){mode=b.getString("audit_mode","compact");super.onCreate(b);}
    JSONObject payloads(Store store)throws Exception{JSONObject out=new JSONObject();try(Cursor cur=store.getReadableDatabase().rawQuery("SELECT id,payload FROM tasks ORDER BY id",null)){while(cur.moveToNext())out.put(Long.toString(cur.getLong(0)),cur.getString(1));}return out;}
    String widgetIds(Context c){int[] ids=android.appwidget.AppWidgetManager.getInstance(c).getAppWidgetIds(new ComponentName(c,TodoWidgetProvider.class));Arrays.sort(ids);return Arrays.toString(ids);}
    boolean scrollFind(String value){for(int n=0;n<24;n++){if(has(value))return true;boolean moved=false;for(AccessibilityNodeInfo item:nodes())if("android.widget.ScrollView".contentEquals(item.getClassName()))moved=item.performAction(AccessibilityNodeInfo.ACTION_SCROLL_FORWARD)||moved;if(!moved)break;pause();}return has(value);}
    @Override public void onStart(){Context c=getTargetContext();Bundle result=new Bundle();int code=Activity.RESULT_OK;android.content.SharedPreferences state=c.getSharedPreferences("audit_lifecycle",0);try{
        if(mode.equals("prepare")){
            try(Store store=new Store(c)){for(Task t:store.all())if(t.title.startsWith("自动测试覆盖安装")){Reminders.cancel(c,t);store.delete(t.id);}Task future=new Task();future.title="自动测试覆盖安装待办";future.date=LocalDate.now().plusDays(3).toString();future.time="11:45";future.endTime="12:30";future.location="虚构楼B207";future.note="保留原文与备注\n第二行";future.remind=true;future.lead=20;store.save(future);Reminders.schedule(c,future);Task done=future.copy();done.id=0;done.title="自动测试覆盖安装已完成";done.done=true;done.remind=false;store.save(done);
                state.edit().putLong("future",future.id).putLong("done",done.id).putString("payloads",payloads(store).toString()).putString("settings",new JSONObject(c.getSharedPreferences("settings",0).getAll()).toString()).putString("widgets",widgetIds(c)).commit();check(true,"Upgrade test records prepared without resetting existing data");}
        }else if(mode.equals("verify")){
            try(Store store=new Store(c)){JSONObject expected=new JSONObject(state.getString("payloads","{}")),actual=payloads(store);check(expected.length()==actual.length(),"Cover install retains every record");for(Iterator<String> it=expected.keys();it.hasNext();){String id=it.next();check(expected.getString(id).equals(actual.getString(id)),"Cover install preserves raw record "+id);}
                Task future=store.find(state.getLong("future",0)),done=store.find(state.getLong("done",0));check(future!=null&&future.remind&&future.lead==20&&future.time.equals("11:45")&&future.endTime.equals("12:30"),"Future reminder and range retained");check(done!=null&&done.done&&!done.remind,"Completed state retained");Intent alarm=new Intent(c,ReminderReceiver.class).setAction("FIRE");check(PendingIntent.getBroadcast(c,(int)future.id,alarm,PendingIntent.FLAG_NO_CREATE|PendingIntent.FLAG_IMMUTABLE)!=null,"Future reminder intent restored after package replacement");}
            JSONObject expected=new JSONObject(state.getString("settings","{}")),actual=new JSONObject(c.getSharedPreferences("settings",0).getAll());for(Iterator<String> it=expected.keys();it.hasNext();){String key=it.next();check(expected.get(key).toString().equals(actual.get(key).toString()),"Cover install retains setting "+key);}check(widgetIds(c).equals(state.getString("widgets","")),"Cover install retains widget bindings");
        }else if(mode.equals("cleanup")){
            try(Store store=new Store(c)){for(Task t:store.all())if(t.title.startsWith("自动测试覆盖安装")){Reminders.cancel(c,t);store.delete(t.id);}}state.edit().clear().commit();check(true,"Only own cover-install fixtures cleaned");
        }else{
            startActivitySync(new Intent(c,MainActivity.class).setFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TASK));waitForIdleSync();check(await("事项清单"),"Compact home opens");check(has("设置")&&has("首页")&&has("日历")&&has("周视图"),"Compact home navigation reachable");capture(c,"audit-compact-home.png");click("＋");check(await("新建事项"),"Compact editor opens");setEdit(0,"明天下午两点在教学楼301教室参加阅读交流会");check(await("14:00")&&has("教学楼301教室"),"Compact editor still recognizes text");check(scrollFind("保存事项"),"Save remains reachable by scrolling");capture(c,"audit-compact-editor.png");click("取消");check(await("事项清单"),"Compact editor cancellation returns home");clickDescription("切换日历");check(await("回到今天"),"Compact calendar opens");capture(c,"audit-compact-calendar.png");clickDescription("切换周视图");check(await("周视图")&&!has("每两小时一格"),"Compact week opens without removed help text");capture(c,"audit-compact-week.png");clickDescription("切换首页");click("设置");check(scrollFind("完成"),"Settings close action remains reachable");click("完成");check(await("事项清单"),"Settings closes on compact layout");
        }
        result.putString("result","PASS: "+checks+" lifecycle/compact checks ("+mode+")");
    }catch(Throwable e){code=Activity.RESULT_CANCELED;result.putString("error",android.util.Log.getStackTraceString(e));}finish(code,result);}
}
